(() => {
  const links = Array.from(document.querySelectorAll('main a')).map(a => a.textContent.trim()).filter(t => t);
  const taskItems = document.querySelectorAll('main ul.list li, main .task, main [class*="task"]');
  return {href: location.href, titles: links, taskItemCount: taskItems.length, bodyText: document.body.innerText.slice(0, 2000)};
})()

(() => {
  const b = document.body.innerText;
  return {
    url: location.href,
    title: document.querySelector('h1') ? document.querySelector('h1').textContent.trim() : null,
    hasDescription: b.includes('fwvk2-n1'),
    descIndex: b.indexOf('fwvk2-n1')
  };
})()

(() => {
  const heads = Array.from(document.querySelectorAll('h1')).map(h => h.textContent.trim());
  const descBlock = document.querySelector('.task-description, [class*="description"]');
  const body = document.body.innerText;
  const m = body.match(/Description[\s\S]{0,200}/);
  return {heads, descText: descBlock ? descBlock.innerText.trim() : null, snippet: m ? m[0] : null};
})()

(() => {
  const inputs = Array.from(document.querySelectorAll('input')).map(i => ({type: i.type, val: i.value, ph: i.placeholder, cls: i.className}));
  const dp = document.querySelector('.flatpickr-calendar');
  const sels = Array.from(document.querySelectorAll('select')).map(s => ({cls: s.className, val: s.value, opts: Array.from(s.options).slice(0,15).map(o=>o.text)}));
  return {inputs, selects: sels, hasFlatpickr: !!dp, dpVisible: dp ? dp.offsetParent !== null : null, dpText: dp ? dp.innerText.slice(0,400) : null};
})()

(() => {
  const dp = document.querySelector('.flatpickr-calendar');
  const monthSel = document.querySelector('.flatpickr-monthDropdown-months');
  const yearInput = document.querySelector('.numInput.cur-year');
  const days = Array.from(document.querySelectorAll('.flatpickr-day')).map(d => ({t: d.textContent.trim(), cls: d.className}));
  const alt = Array.from(document.querySelectorAll('input[type=text]')).map(i=>i.value);
  return {visible: dp?dp.offsetParent!==null:false, month: monthSel?monthSel.value:null, year: yearInput?yearInput.value:null, days, alt};
})()

(() => {
  const btns = Array.from(document.querySelectorAll('button')).filter(b=>b.offsetParent!==null).map(b=>b.textContent.trim()).filter(t=>t);
  const dp = document.querySelector('.flatpickr-calendar');
  return {visibleBtns: btns.slice(0,60), dpVisible: dp?dp.offsetParent!==null:false};
})()

(() => {
  const dueBtn = Array.from(document.querySelectorAll('button')).find(b=>/Set Due Date|Due Date/i.test(b.textContent) && b.closest('main'));
  const prio = Array.from(document.querySelectorAll('button')).filter(b=>b.closest('main')).map(b=>b.textContent.trim());
  // find date/time section
  const main = document.querySelector('main');
  return {
    buttonsWithDateOrPrio: prio.filter(t=>/Date|Priorit|High|Medium|Low|Urgent|Unset|Dec/i.test(t)),
    mainText: main.innerText
  };
})()

(() => {
  const sels = Array.from(document.querySelectorAll('select')).map(s=>({cls:s.className, val:s.value, vis: s.offsetParent!==null, opts: Array.from(s.options).map(o=>o.text)}));
  // priority display in Vikunja: .priority or the popup
  const prioEl = document.querySelector('main .priority, main [class*="priority"]');
  return {selects: sels, prioElText: prioEl?prioEl.innerText:null};
})()

(() => {
  const ms = document.querySelectorAll('.multiselect');
  const out = [];
  ms.forEach((m,i) => out.push({i, vis: m.offsetParent!==null, text: m.innerText.slice(0,300)}));
  const sugg = Array.from(document.querySelectorAll('.multiselect__element, .multiselect__option')).map(o=>({t:o.innerText.trim(), cls:o.className}));
  return {ms: out, sugg};
})()

(() => {
  const main = document.querySelector('main');
  const ms = Array.from(document.querySelectorAll('.multiselect')).map(m=>({vis:m.offsetParent!==null, t:m.innerText.replace(/\n/g,' | ').slice(0,200)}));
  return {mainText: main.innerText.slice(0,1200), multiselects: ms};
})()

(() => {
  const c = document.querySelector('#comments, .comments, [class*="comment"]');
  const all = Array.from(document.querySelectorAll('main *')).filter(el => el.children.length===0 && el.textContent.includes('fwvk2-n1'));
  return {commentRegion: c ? c.innerText.slice(0,600) : null, matches: all.map(e=>e.textContent.trim())};
})()

(() => {
  const figs = Array.from(document.querySelectorAll('main figure')).map(f => f.innerText.replace(/\s+/g,' ').trim());
  const desc = document.querySelector('main [class*="description"], main .task-description');
  const title = Array.from(document.querySelectorAll('main h1')).map(h=>h.textContent.trim());
  const lab = Array.from(document.querySelectorAll('main .multiselect__tag, main [class*="label"] .tag')).map(t=>t.innerText.trim());
  const prio = document.querySelector('main select') ? document.querySelector('main select').selectedOptions[0].text : null;
  const due = (() => { const b = Array.from(document.querySelectorAll('main button')).find(x=>/\d{1,2} \w{3} \d{4}/.test(x.innerText)); return b?b.innerText.trim():null; })();
  return {title, figCount: figs.length, figs, descText: desc?desc.innerText.trim():null, labels: lab, priority: prio, due};
})()

(() => {
  const h = Array.from(document.querySelectorAll('main h3')).find(x=>/Comments/.test(x.textContent));
  const container = h ? h.closest('div') : null;
  const sec = h ? h.parentElement : null;
  const commentsCol = h ? h.closest('[class*="comments"], .comments') : null;
  const target = commentsCol || sec;
  const text = target ? target.innerText.replace(/\s+/g,' ').trim() : null;
  const ps = Array.from(document.querySelectorAll('main p')).map(p=>p.textContent.trim()).filter(t=>t);
  return {containerClass: target?target.className:null, text, allParagraphsInMain: ps};
})()
